const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const raiz = path.resolve(__dirname, '..')
const ui = fs.readFileSync(path.join(raiz,'components/whatsapp/FichaContatoWhatsApp.tsx'),'utf8')
const tela = fs.readFileSync(path.join(raiz,'app/whatsapp/page.tsx'),'utf8')
const api = fs.readFileSync(path.join(raiz,'app/api/integracoes/whatsapp/cadastrar-contato/route.ts'),'utf8')

assert.ok(ui.includes('Contato não salvo'))
assert.ok(ui.includes('Cadastrar contato no Cliente 360'))
for (const campo of ['Nome completo','Empresa / organização','E-mail','WhatsApp principal','Telefone secundário','CPF / CNPJ','Cidade','Bairro','Endereço','Observações']) {
  assert.ok(ui.includes(campo), 'Ausente: '+campo)
}
assert.ok(ui.includes('max-h-[42dvh] overflow-y-auto'), 'Cadastro não pode empurrar chat para fora')
assert.ok(ui.includes('aoCadastrar(json.cliente)'), 'Cadastro deve refletir na conversa')
assert.ok(tela.includes("ativa.whatsapp_chat_tipo !== 'grupo' && ("), 'Grupos sem alteração no cabeçalho')
assert.ok(tela.includes('<FichaContatoWhatsApp'), 'Ficha renderizada no WhatsApp')
assert.ok(tela.includes('cliente_id:novo.id'), 'Cliente 360 vinculado')
assert.ok(tela.includes('select(\'id,nome,whatsapp,telefone,email,cidade,endereco,bairro,observacoes\')'))
assert.ok(api.includes('const usuario = await autenticarTenant(req)'), 'Autenticação obrigatória')
assert.ok(api.includes('await conversaAcessivel(conversaId, usuario, true)'), 'Autorização da conversa no servidor')
assert.ok(api.includes("conversa.whatsapp_chat_tipo === 'grupo'"), 'Bloqueio de grupos')
assert.ok(api.includes(".eq('empresa_id', usuario.empresa_id)"), 'Isolamento por empresa')
assert.ok(api.includes(".is('cliente_id', null)"), 'Não sobrescrever Cliente 360')
assert.ok(api.includes('clienteExistente'), 'Evitar cadastro duplicado')
assert.ok(api.includes("body?.confirmarVinculo !== true"), 'Confirmar vínculo existente')
assert.ok(api.includes("origem: 'whatsapp'"), 'Origem CRM correta')
assert.ok(api.includes("whatsapp = digitos(conversa.telefone)"), 'Telefone seguro da conversa')
assert.ok(!api.includes('body?.whatsapp'), 'Não aceitar telefone do cliente como verdade')
assert.ok(api.includes("tipo: existente ? 'contato_existente_vinculado' : 'contato_cadastrado_whatsapp'"), 'Auditoria cadastral')
const gateway = fs.readFileSync(path.join(raiz,'supabase/functions/whatsapp-gateway/index.ts'),'utf8')
const server = fs.readFileSync(path.join(raiz,'lib/whatsappServer.ts'),'utf8')
assert.ok(gateway.includes('!isGroup && existing.cliente_id'), 'Nome persistido vence apelido WhatsApp')
assert.ok(server.includes('atual.cliente_id ? (cliente as any)?.nome || atual.contato_nome'), 'Fluxo Meta preserva cadastro')
console.log('OK: 25 verificações da ficha, cadastro e segurança do WhatsApp')
